/bin/zsh -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#0b1018">
<title>Codex</title>
<style>
  :root {
    color-scheme: dark;
    --ink: #eef3f8;
    --muted: #8995a4;
    --line: rgba(218, 231, 244, .1);
    --panel: #111923;
    --panel-hi: #17212c;
    --accent: #f5a94a;
    --mint: #8de1c1;
  }
  * { box-sizing: border-box; }
  html, body { width: 100%; height: 100%; margin: 0; }
  body {
    overflow: hidden;
    background: #0b1018;
    color: var(--ink);
    font: 14px/1.4 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    letter-spacing: .01em;
  }
  button, input { font: inherit; }
  .app { width: 100%; height: 100%; display: grid; grid-template-rows: 62px minmax(0, 1fr); }
  .topbar {
    display: flex; align-items: center; justify-content: space-between; padding: 0 25px;
    border-bottom: 1px solid var(--line); background: rgba(12, 17, 25, .94); z-index: 2;
  }
  .brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
  .brand-mark { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid rgba(245,169,74,.42); border-radius: 9px; color: var(--accent); background: rgba(245,169,74,.08); }
  .brand-mark svg { width: 18px; height: 18px; }
  h1 { font-size: 16px; line-height: 1; font-weight: 720; margin: 0; letter-spacing: -.025em; }
  .brand-kicker { margin-left: 1px; font-size: 10px; text-transform: uppercase; letter-spacing: .15em; color: #8290a0; }
  .session { display: flex; align-items: center; gap: 9px; color: #98a5b3; font-size: 11px; letter-spacing: .12em; text-transform: uppercase; }
  .session-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 12px rgba(141,225,193,.7); }
  .workspace { min-height: 0; display: grid; grid-template-columns: 315px minmax(0, 1fr); }
  .sidebar { min-height: 0; overflow: auto; padding: 20px 17px 22px; background: #101720; border-right: 1px solid var(--line); scrollbar-color: #374352 transparent; }
  .section-heading { display: flex; align-items: baseline; justify-content: space-between; margin: 0 2px 16px; }
  .section-heading h2 { margin: 0; font-size: 13px; font-weight: 650; letter-spacing: .02em; }
  .section-heading span { color: #718092; font-size: 10px; text-transform: uppercase; letter-spacing: .13em; }
  .control-card { padding: 15px 14px 13px; border: 1px solid rgba(218,231,244,.095); border-radius: 12px; background: linear-gradient(145deg, rgba(255,255,255,.028), rgba(255,255,255,.008)); }
  .control-row { margin-bottom: 17px; }
  .control-row:last-of-type { margin-bottom: 14px; }
  .control-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 7px; }
  .control-head label { color: #c5ced8; font-size: 11px; font-weight: 540; }
  .value { min-width: 52px; color: var(--ink); text-align: right; font-variant-numeric: tabular-nums; font-size: 12px; font-weight: 650; }
  .value small { margin-left: 3px; color: #7f8c9b; font-size: 10px; font-weight: 450; }
  input[type="range"] { width: 100%; height: 4px; display: block; margin: 0; appearance: none; border-radius: 9px; background: linear-gradient(90deg, var(--accent) 0%, var(--accent) var(--fill,50%), #33404d var(--fill,50%), #33404d 100%); outline: 0; cursor: pointer; }
  input[type="range"]::-webkit-slider-thumb { appearance: none; width: 13px; height: 13px; border: 2px solid #111923; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
  input[type="range"]::-moz-range-thumb { width: 10px; height: 10px; border: 2px solid #111923; border-radius: 50%; background: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
  .range-ends { display: flex; justify-content: space-between; margin-top: 5px; color: #627181; font-size: 9px; font-variant-numeric: tabular-nums; }
  .button-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 19px; }
  .button-row button { min-height: 39px; border-radius: 8px; cursor: pointer; transition: transform .14s ease, border-color .14s ease, background .14s ease; }
  .button-row button:active { transform: translateY(1px); }
  .test-button { border: 1px solid #ffbd69; color: #20160b; background: linear-gradient(180deg, #ffc575, #f4a344); box-shadow: 0 5px 18px rgba(238,149,53,.15); font-size: 12px; font-weight: 760; }
  .test-button:hover { background: linear-gradient(180deg, #ffd08e, #ffae4d); }
  .reset-button { border: 1px solid rgba(210,225,240,.15); color: #c4ced8; background: rgba(255,255,255,.035); font-size: 12px; font-weight: 600; }
  .reset-button:hover { background: rgba(255,255,255,.075); border-color: rgba(210,225,240,.28); }
  .helper { margin: 11px 1px 0; color: #748191; font-size: 10px; line-height: 1.55; }
  .telemetry { margin-top: 17px; overflow: hidden; border: 1px solid rgba(218,231,244,.09); border-radius: 11px; background: rgba(255,255,255,.018); }
  .telemetry-title { display: flex; align-items: center; justify-content: space-between; padding: 11px 12px 9px; border-bottom: 1px solid var(--line); color: #aab5c0; font-size: 10px; text-transform: uppercase; letter-spacing: .12em; }
  .telemetry-title span:last-child { color: #758394; font-size: 9px; letter-spacing: .08em; }
  .telemetry-grid { display: grid; grid-template-columns: 1fr 1fr; padding: 4px 5px; }
  .metric { padding: 9px 8px 8px; }
  .metric:nth-child(odd) { border-right: 1px solid var(--line); }
  .metric:nth-child(-n+2) { border-bottom: 1px solid var(--line); }
  .metric-label { color: #788696; font-size: 9px; text-transform: uppercase; letter-spacing: .1em; }
  .metric-value { margin-top: 4px; color: #e8edf2; font-size: 17px; font-variant-numeric: tabular-nums; letter-spacing: -.03em; }
  .metric-value small { margin-left: 3px; color: #82909e; font-size: 10px; letter-spacing: 0; }
  .constants { margin-top: 15px; padding: 0 2px; }
  .constants summary { list-style: none; display: flex; align-items: center; justify-content: space-between; padding: 6px 1px; color: #8794a2; cursor: pointer; font-size: 10px; text-transform: uppercase; letter-spacing: .1em; }
  .constants summary::-webkit-details-marker { display: none; }
  .constants summary::after { content: "+"; color: #748293; font-size: 15px; line-height: 10px; }
  .constants[open] summary::after { content: "−"; }
  .constant-list { display: grid; grid-template-columns: 1fr auto; gap: 7px 10px; padding: 8px 1px 4px; color: #7f8c9b; font-size: 10px; }
  .constant-list span:nth-child(even) { color: #c2cbd4; text-align: right; font-variant-numeric: tabular-nums; }
  .stage { position: relative; min-width: 0; min-height: 0; overflow: hidden; background: #17212a; }
  canvas { display: block; width: 100%; height: 100%; }
  .canvas-topline { position: absolute; top: 17px; left: 19px; right: 19px; display: flex; align-items: flex-start; justify-content: space-between; pointer-events: none; }
  .experiment-label { display: grid; gap: 3px; text-shadow: 0 2px 10px rgba(0,0,0,.3); }
  .experiment-label strong { color: rgba(241,246,250,.94); font-size: 11px; font-weight: 650; letter-spacing: .13em; text-transform: uppercase; }
  .experiment-label span { color: rgba(190,203,215,.66); font-size: 10px; }
  .run-state { display: inline-flex; align-items: center; gap: 7px; padding: 7px 10px; border: 1px solid rgba(227,237,246,.16); border-radius: 999px; color: #d1d9e0; background: rgba(13,20,28,.48); backdrop-filter: blur(10px); font-size: 9px; text-transform: uppercase; letter-spacing: .12em; }
  .run-state i { width: 6px; height: 6px; border-radius: 50%; background: #8de1c1; box-shadow: 0 0 9px rgba(141,225,193,.6); }
  .run-state.running i { background: var(--accent); box-shadow: 0 0 9px rgba(245,169,74,.75); }
  .canvas-caption { position: absolute; left: 19px; bottom: 15px; color: rgba(206,216,225,.52); font-size: 9px; text-transform: uppercase; letter-spacing: .13em; pointer-events: none; }
  @media (max-width: 850px) {
    body { overflow: auto; }
    .app { min-height: 100%; height: auto; grid-template-rows: 56px auto; }
    .topbar { padding: 0 15px; }
    .workspace { grid-template-columns: minmax(0,1fr); grid-template-rows: auto minmax(440px, 58vh); }
    .sidebar { max-height: none; overflow: visible; padding: 15px; border-right: 0; border-bottom: 1px solid var(--line); }
    .control-card { padding: 13px 12px 11px; }
    .control-card .control-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 18px; }
    .control-row { margin-bottom: 13px; }
    .telemetry { margin-top: 12px; }
    .constants { margin-top: 9px; }
    .stage { min-height: 440px; }
  }
  @media (max-width: 480px) {
    .session { font-size: 9px; }
    .brand-kicker { font-size: 8px; }
    .workspace { grid-template-rows: auto minmax(390px, 52vh); }
    .sidebar { padding: 12px; }
    .control-card .control-grid { gap: 0 12px; }
    .control-head label { font-size: 10px; }
    .metric-value { font-size: 15px; }
    .canvas-topline { top: 12px; left: 12px; right: 12px; }
    .canvas-caption { left: 12px; bottom: 10px; }
  }
</style>
</head>
<body>
<div class="app">
  <header class="topbar">
    <div class="brand">
      <span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="M4 17.5 12 4l8 13.5H4Z" stroke="currentColor" stroke-width="1.7"/><path d="M8 17.5 12 11l4 6.5" stroke="currentColor" stroke-width="1.5" opacity=".7"/></svg></span>
      <h1>Codex</h1><span class="brand-kicker">Impact lab · 2D</span>
    </div>
    <div class="session"><span class="session-dot"></span><span>Experiment 01</span></div>
  </header>
  <main class="workspace">
    <aside class="sidebar" aria-label="Experiment settings and readouts">
      <div class="section-heading"><h2>Experiment setup</h2><span>SI units</span></div>
      <section class="control-card" aria-label="Adjust experiment parameters">
        <div class="control-grid">
          <div class="control-row">
            <div class="control-head"><label for="speed">Car speed</label><span class="value" id="speedValue">22<small>m/s</small></span></div>
            <input id="speed" type="range" min="5" max="45" step="1" value="22" aria-label="Car speed in meters per second"><div class="range-ends"><span>5 m/s</span><span>45 m/s</span></div>
          </div>
          <div class="control-row">
            <div class="control-head"><label for="columns">Wall columns</label><span class="value" id="columnsValue">12<small>bricks</small></span></div>
            <input id="columns" type="range" min="4" max="24" step="1" value="12" aria-label="Wall columns"><div class="range-ends"><span>4</span><span>24</span></div>
          </div>
          <div class="control-row">
            <div class="control-head"><label for="rows">Wall rows</label><span class="value" id="rowsValue">8<small>bricks</small></span></div>
            <input id="rows" type="range" min="3" max="16" step="1" value="8" aria-label="Wall rows"><div class="range-ends"><span>3</span><span>16</span></div>
          </div>
          <div class="control-row">
            <div class="control-head"><label for="layers">Wall depth</label><span class="value" id="layersValue">2<small>layers</small></span></div>
            <input id="layers" type="range" min="1" max="5" step="1" value="2" aria-label="Wall depth layers"><div class="range-ends"><span>1 layer</span><span>5 layers</span></div>
          </div>
          <div class="control-row">
            <div class="control-head"><label for="mass">Brick mass</label><span class="value" id="massValue">2.5<small>kg</small></span></div>
            <input id="mass" type="range" min="0.5" max="12" step="0.1" value="2.5" aria-label="Brick mass in kilograms"><div class="range-ends"><span>0.5 kg</span><span>12 kg</span></div>
          </div>
        </div>
        <div class="button-row"><button type="button" class="test-button" id="testButton">Test</button><button type="button" class="reset-button" id="resetButton">Reset</button></div>
        <p class="helper">Each run rebuilds the same wall and starts from rest. Bricks and mortar joints use a deterministic 2D rigid-body model.</p>
      </section>
      <section class="telemetry" aria-label="Live experiment telemetry">
        <div class="telemetry-title"><span>Live telemetry</span><span id="phaseLabel">READY</span></div>
        <div class="telemetry-grid">
          <div class="metric"><div class="metric-label">Car speed</div><div class="metric-value"><span id="speedReadout">0.0</span><small>m/s</small></div></div>
          <div class="metric"><div class="metric-label">Elapsed</div><div class="metric-value"><span id="timeReadout">0.00</span><small>s</small></div></div>
          <div class="metric"><div class="metric-label">Moving bricks</div><div class="metric-value"><span id="movingReadout">0</span></div></div>
          <div class="metric"><div class="metric-label">Mortar joints</div><div class="metric-value"><span id="jointReadout">0</span><small>intact</small></div></div>
        </div>
      </section>
      <details class="constants">
        <summary>Fixed physical constants</summary>
        <div class="constant-list">
          <span>Brick size</span><span>0.50 × 0.24 m</span>
          <span>Brick friction</span><span>0.72</span>
          <span>Brick restitution</span><span>0.18</span>
          <span>Car mass</span><span>1,250 kg</span>
          <span>Car body</span><span>4.2 × 1.45 m</span>
          <span>Ground friction</span><span>0.85</span>
          <span>Gravity</span><span>9.81 m/s²</span>
          <span>Simulation scale</span><span>80 px/m</span>
        </div>
      </details>
    </aside>
    <section class="stage" aria-label="Side view crash experiment">
      <canvas id="scene" aria-label="Animated side view of a car and individual brick wall"></canvas>
      <div class="canvas-topline"><div class="experiment-label"><strong>Crash test · side view</strong><span>Freestanding staggered masonry · metric track</span></div><div class="run-state" id="runState"><i></i><span>Ready</span></div></div>
      <div class="canvas-caption">Illustrative 2D cross-section · gravity and contact in SI units</div>
    </section>
  </main>
</div>
<script>
(function () {
  "use strict";
  const canvas = document.getElementById("scene");
  const ctx = canvas.getContext("2d", { alpha: false });
  const controls = {
    speed: document.getElementById("speed"),
    columns: document.getElementById("columns"),
    rows: document.getElementById("rows"),
    layers: document.getElementById("layers"),
    mass: document.getElementById("mass")
  };
  const values = {
    speed: document.getElementById("speedValue"),
    columns: document.getElementById("columnsValue"),
    rows: document.getElementById("rowsValue"),
    layers: document.getElementById("layersValue"),
    mass: document.getElementById("massValue")
  };
  const cfg = {
    brickW: 0.50, brickH: 0.24, gravity: 9.81, brickFriction: 0.72,
    brickRestitution: 0.18, carMass: 1250, carW: 4.2, carH: 1.45,
    groundFriction: 0.85, nominalScale: 80, wallX: 13.4,
    carStartX: 2.2, carStartY: 0.76, fixedDt: 1 / 120
  };
  let settings = readSettings();
  let bodies = [];
  let joints = [];
  let car = null;
  let particles = [];
  let state = "ready";
  let elapsed = 0;
  let accumulator = 0;
  let lastFrame = 0;
  let cameraX = 0;
  let cameraScale = 50;
  let groundYpx = 0;
  let dpr = 1;
  let width = 0;
  let height = 0;
  let sceneRight = 21;
  let impactFlash = 0;
  let shake = 0;
  let settleClock = 0;
  let quietClock = 0;
  let impactSeen = false;
  let seed = 123456789;
  let currentImpactForce = 0;
  let lastParticleTime = -10;

  function readSettings() {
    return {
      speed: Number(controls.speed.value),
      columns: Number(controls.columns.value),
      rows: Number(controls.rows.value),
      layers: Number(controls.layers.value),
      mass: Number(controls.mass.value)
    };
  }
  function updateValueLabels() {
    const format = { speed: [String(settings.speed), "m/s"], columns: [String(settings.columns), "bricks"], rows: [String(settings.rows), "bricks"], layers: [String(settings.layers), "layers"], mass: [settings.mass.toFixed(1), "kg"] };
    Object.keys(controls).forEach(function (key) {
      values[key].innerHTML = format[key][0] + "<small>" + format[key][1] + "</small>";
      const min = Number(controls[key].min), max = Number(controls[key].max);
      const pct = (Number(controls[key].value) - min) / (max - min) * 100;
      controls[key].style.setProperty("--fill", pct + "%");
    });
  }
  function bodyCreate(props) {
    const b = Object.assign({
      vx: 0, vy: 0, angle: 0, omega: 0, fx: 0, fy: 0,
      invMass: 0, invI: 0, kind: "brick", layer: 0, row: 0, col: 0,
      friction: cfg.brickFriction, restitution: cfg.brickRestitution,
      moving: false, shade: 0, color: "#a45039"
    }, props);
    b.mass = props.mass;
    b.invMass = 1 / b.mass;
    b.inertia = b.mass * (b.w * b.w + b.h * b.h) / 12;
    b.invI = 1 / b.inertia;
    return b;
  }
  function buildScene(launch) {
    settings = readSettings();
    bodies = [];
    joints = [];
    particles = [];
    elapsed = 0;
    accumulator = 0;
    settleClock = 0;
    quietClock = 0;
    impactSeen = false;
    impactFlash = 0;
    shake = 0;
    currentImpactForce = 0;
    lastParticleTime = -10;
    seed = 123456789;
    const carBody = bodyCreate({
      kind: "car", x: cfg.carStartX, y: cfg.carStartY, w: cfg.carW, h: 0.90,
      mass: cfg.carMass, friction: cfg.groundFriction, restitution: 0.07,
      color: "#d98b3b", layer: -1
    });
    car = carBody;
    bodies.push(carBody);
    const brickGrid = [];
    const palette = ["#a84e37", "#b0563d", "#9c4734", "#ad523a", "#a34a36", "#b45c41"];
    for (let layer = 0; layer < settings.layers; layer++) {
      brickGrid[layer] = [];
      for (let row = 0; row < settings.rows; row++) {
        brickGrid[layer][row] = [];
        const stagger = (row % 2) * cfg.brickW * 0.5;
        for (let col = 0; col < settings.columns; col++) {
          const x = cfg.wallX + col * cfg.brickW + cfg.brickW * 0.5 + cfg.brickW * 0.5 - stagger;
          const y = row * cfg.brickH + cfg.brickH * 0.5;
          const tone = (row * 5 + col * 3 + layer * 2) % palette.length;
          const brick = bodyCreate({
            kind: "brick", x: x, y: y, w: cfg.brickW, h: cfg.brickH,
            mass: settings.mass, layer: layer, row: row, col: col,
            friction: cfg.brickFriction, restitution: cfg.brickRestitution,
            color: palette[tone], shade: (col * 7 + row * 3 + layer * 5) % 9
          });
          brickGrid[layer][row][col] = brick;
          bodies.push(brick);
        }
      }
      for (let row = 0; row < settings.rows; row++) {
        for (let col = 0; col < settings.columns - 1; col++) {
          makeJoint(brickGrid[layer][row][col], brickGrid[layer][row][col + 1], "horizontal");
        }
      }
      for (let row = 0; row < settings.rows - 1; row++) {
        for (let col = 0; col < settings.columns; col++) {
          const lower = brickGrid[layer][row][col];
          const lowerLeft = lower.x - lower.w / 2;
          const lowerRight = lower.x + lower.w / 2;
          for (let upperCol = 0; upperCol < settings.columns; upperCol++) {
            const upper = brickGrid[layer][row + 1][upperCol];
            const overlapLeft = Math.max(lowerLeft, upper.x - upper.w / 2);
            const overlapRight = Math.min(lowerRight, upper.x + upper.w / 2);
            if (overlapRight - overlapLeft > 0.015) {
              const anchor = { x: (overlapLeft + overlapRight) / 2, y: (lower.y + lower.h / 2 + upper.y - upper.h / 2) / 2 };
              makeJointAt(lower, upper, anchor, "vertical");
            }
          }
        }
      }
    }
    sceneRight = cfg.wallX + settings.columns * cfg.brickW + 0.75;
    cameraX = 0.1;
    state = launch ? "running" : "ready";
    updateStateLabel();
    updateTelemetry();
    if (launch) {
      settleClock = 0;
      car.vx = 0;
    }
  }
  function makeJoint(a, b, type) {
    const point = type === "horizontal"
      ? { x: (a.x + a.w / 2 + b.x - b.w / 2) / 2, y: (a.y + b.y) / 2 }
      : { x: (a.x + b.x) / 2, y: (a.y + a.h / 2 + b.y - b.h / 2) / 2 };
    makeJointAt(a, b, point, type);
  }
  function makeJointAt(a, b, point, type) {
    const strength = 6100 * Math.sqrt(settings.mass / 2.5);
    joints.push({
      a: a, b: b, localA: toLocal(a, point), localB: toLocal(b, point),
      angle0: b.angle - a.angle, fx: 0, fy: 0, torque: 0,
      maxForce: strength, maxTorque: strength * 0.19, type: type, broken: false
    });
  }
  function toLocal(body, point) {
    const dx = point.x - body.x, dy = point.y - body.y;
    const c = Math.cos(body.angle), s = Math.sin(body.angle);
    return { x: dx * c + dy * s, y: -dx * s + dy * c };
  }
  function jointAnchor(body, local) {
    const c = Math.cos(body.angle), s = Math.sin(body.angle);
    return { x: body.x + local.x * c - local.y * s, y: body.y + local.x * s + local.y * c };
  }
  function worldVertices(body, dx, dy) {
    const hx = body.w / 2, hy = body.h / 2;
    const c = Math.cos(body.angle), s = Math.sin(body.angle);
    const coords = [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]];
    return coords.map(function (p) { return { x: body.x + p[0] * c - p[1] * s + (dx || 0), y: body.y + p[0] * s + p[1] * c + (dy || 0) }; });
  }
  function axes(body) {
    const c = Math.cos(body.angle), s = Math.sin(body.angle);
    return [{ x: c, y: s }, { x: -s, y: c }];
  }
  function projectRadius(body, axis) {
    const a = axes(body);
    return Math.abs(axis.x * a[0].x + axis.y * a[0].y) * body.w / 2 + Math.abs(axis.x * a[1].x + axis.y * a[1].y) * body.h / 2;
  }
  function support(body, dir) {
    const verts = worldVertices(body);
    let max = -Infinity, sx = 0, sy = 0, count = 0;
    for (let i = 0; i < verts.length; i++) {
      const v = verts[i], value = v.x * dir.x + v.y * dir.y;
      if (value > max + 1e-7) { max = value; sx = v.x; sy = v.y; count = 1; }
